// ---- crowd chant sample (chant events + title change) ----
const CHANT_SRC='data:audio/mpeg;base64,';
const CHANTB={b:null,ld:false};
function chantLoad(c){if(CHANTB.ld||!c)return;CHANTB.ld=true;try{const bin=atob(CHANT_SRC.split(',')[1]),u=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)u[i]=bin.charCodeAt(i);const p=c.decodeAudioData(u.buffer,b=>{CHANTB.b=b},()=>{});if(p&&p.catch)p.catch(()=>{})}catch(e){}}
SFX.chant=function(vol){try{const c=sndCtx();if(!c||!sndOk('chant',1500))return;chantLoad(c);if(!CHANTB.b)return;const s=c.createBufferSource();s.buffer=CHANTB.b;const g=c.createGain();g.gain.value=vol||.6;s.connect(g);g.connect(SND.master);s.start()}catch(e){}};
(function(){const _om=openModal;openModal=function(h){const r=_om.apply(this,arguments);
  try{if(typeof h==='string'&&h.indexOf('data-act="evopt"')>=0){const mt=h.match(/<h2>(.*?)<\/h2>/);if(mt&&/skanduj|okrzyk|dudni|hymn|chant|anthem/i.test(mt[1]))setTimeout(()=>sPlay('chant'),350)}}catch(e){}
  return r};
 const _fa=SFX.fanfare;SFX.fanfare=function(){const r=_fa.apply(this,arguments);try{setTimeout(()=>sPlay('chant',.45),700)}catch(e){}return r};
 try{if(typeof window!=='undefined')window.addEventListener('pointerdown',()=>{try{const c=sndCtx();if(c)chantLoad(c)}catch(e){}},{once:true,capture:true})}catch(e){}})();
